-- Fixture run history for the flake detector reader.
-- Schema mirrors the detector's .flake/history.db (see docs/data-format.md).
-- Build fixtures/acme-shop/.flake/history.db from this file with: npm run fixtures

CREATE TABLE schema_version (
  version INTEGER NOT NULL
);

CREATE TABLE build_run (
  id INTEGER PRIMARY KEY,
  workflow_run_id TEXT NOT NULL,
  attempt INTEGER NOT NULL DEFAULT 1,
  commit_sha TEXT NOT NULL,
  branch TEXT NOT NULL,
  timestamp TEXT NOT NULL
);

CREATE TABLE test_run (
  id INTEGER PRIMARY KEY,
  build_run_id INTEGER NOT NULL REFERENCES build_run (id),
  class_name TEXT NOT NULL,
  method_name TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  commit_sha TEXT NOT NULL,
  branch TEXT NOT NULL,
  runner TEXT,
  duration_ms INTEGER NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('PASS', 'FAIL', 'ERROR', 'SKIPPED')),
  failure_hash TEXT
);

CREATE INDEX test_run_by_test ON test_run (class_name, method_name, timestamp);


